// @vitest-environment node
/**
 * Release 24: the legacy ferry site's handoff script (public/handoff-ferry.js at the repo root, generated by @bft/ui/redirect's
 * legacyFerryHandoffJs). The committed file is this output (UPDATE_HANDOFF=1 rewrites it), and it hands a remembered
 * pair to the same transit page the 301 goes to.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { runInNewContext } from 'node:vm'
import { decodeHandoff, HANDOFF_PREFIX } from '@bft/ui/handoff-codec'
import { legacyFerryHandoffJs } from '@bft/ui/redirect'
import { describe, expect, it } from 'vitest'

const T = 'https://brisbanetransit.com'
const FILE = fileURLToPath(new URL('../../../public/handoff-ferry.js', import.meta.url))
const PAIR = { outbound: { id: '317584', name: 'Bulimba' }, inbound: { id: '317590', name: 'Riverside' } }

/** Runs the committed script as a legacy page at `url` with this storage: where it went and the cookies it set. */
function run(url: string, local: Record<string, string> = {}) {
  const u = new URL(url)
  let went: string | null = null
  const cookies: string[] = []
  const appended: { id?: string; href?: string }[] = []
  const storage = (items: Record<string, string>) => ({
    getItem: (k: string) => (Object.hasOwn(items, k) ? (items[k] as string) : null),
    setItem: (k: string, v: string) => {
      items[k] = v
    },
  })
  const document = {
    createElement: () => ({}) as { id?: string; href?: string },
    head: { appendChild: (a: { id?: string; href?: string }) => appended.push(a) },
    getElementById: (id: string) => appended.find((a) => a.id === id) ?? null,
    get cookie() {
      return ''
    },
    set cookie(v: string) {
      cookies.push(v)
    },
  }
  const location = {
    hostname: u.hostname,
    pathname: u.pathname,
    search: u.search,
    replace: (to: string) => {
      went = to
    },
  }
  const window = { localStorage: storage(local) }
  runInNewContext(readFileSync(FILE, 'utf8'), {
    document,
    location,
    window,
    sessionStorage: storage({}),
    TextEncoder,
    btoa,
  })
  return { went: went as string | null, cookies }
}

describe('legacy ferry handoff (public/handoff-ferry.js)', () => {
  it('is the generator output', () => {
    const want = legacyFerryHandoffJs(T)
    if (process.env.UPDATE_HANDOFF === '1') writeFileSync(FILE, want)
    expect(readFileSync(FILE, 'utf8')).toBe(want)
  })

  it('a remembered pair goes to transit in the fragment, on the page the 301 would go to', () => {
    const local = {
      'brisbane-ferry-selected-stops': JSON.stringify(PAIR),
      'brisbane-ferry-remember-selection': 'true',
    }
    const home = run('https://www.brisbaneferry.com/?utm_source=x', local)
    expect(home.went?.startsWith(`${T}/ferry/?utm_source=x${HANDOFF_PREFIX}`)).toBe(true)
    const went = home.went as string
    const payload = decodeHandoff(went.slice(went.indexOf(HANDOFF_PREFIX)))
    expect(payload?.ferry).toEqual({ pair: PAIR, remember: true })
    // Favourites to hand over: no handed-off cookie, so the next visit hands them over again (idempotent import).
    expect(home.cookies).toEqual([])
    for (const path of ['/terminal/bulimba', '/terminal/bulimba/', '/terminal/bulimba/index.html'])
      expect(run(`https://www.brisbaneferry.com${path}`, local).went?.split('#')[0]).toBe(
        `${T}/ferry/terminal/bulimba`,
      )
  })

  it('nothing to hand over: the plain transit page, and the cookie that sends later visits the 301', () => {
    const r = run('https://www.brisbaneferry.com/terminal/riverside?x=1')
    expect(r.went).toBe(`${T}/ferry/terminal/riverside?x=1`)
    expect(r.cookies).toEqual(['bft-handoff=1; Max-Age=31536000; Path=/; Secure; SameSite=Lax'])
  })

  it('does nothing on any other host (the iOS app, previews, local dev)', () => {
    for (const url of [
      'capacitor://localhost/',
      'https://brisbane-ferry-tracker-git-develop-starblaze.vercel.app/',
      'http://localhost:5173/',
      'https://ferry.lifemap.au/',
      'https://www.brisbaneferry.com.evil.example/',
    ])
      expect(run(url).went, url).toBeNull()
  })
})
